from pathlib import Path
import json,csv,datetime,html,textwrap
root=Path(__file__).resolve().parents[1]; out=root/'november'
weeks=['حضورك أهم من خوفك','جودة الشغل من جوّه','كمّل بقدرتك الحقيقية','ثبات من غير قسوة','حصاد بلا محاكمة']
diagrams={3:('من مشاهدة الحل لفهمه',['راجع إجابتك الحالية','حدّد أول اختلاف','افهم سبب الخطوة','كمّل التصحيح المقرر']),4:('الرجوع من السرحان',['لاحظ السرحان','حدّد آخر سطر فاهمه','ارجع له بهدوء','كمّل نفس المهمة']),5:('الغلطة بتقول إيه؟',['هل فهمت المطلوب؟','هل الفكرة واضحة؟','هل التنفيذ دقيق؟','صحّح السبب في مراجعتك']),8:('قبل ما القلم يتحرك',['اقرأ السؤال كاملًا','لاحظ فعل الطلب','حدّد المطلوب','جاوب على نفس المطلوب']),13:('قبل فتح الإجابة',['اقرأ السؤال الحالي','حدّد المعطى والمطلوب','ابدأ بما تعرفه','اطلب مساعدة عند التعثر']),19:('اختار شكل الإجابة',['قارن ← طرفان وعلاقة','علّل ← سبب يفسّر','عرّف ← معنى محدد','التزم بمنهجك وتعليمات مدرسك']),25:('الدقة وقت التعويض',['القيمة المستخدمة','الإشارة الصحيحة','الوحدة المطلوبة','انتباه داخل نفس الحل']),27:('هل السؤال اكتمل؟',['ارجع للمطلوب','طابقه بإجابتك','لاحظ الأجزاء المتبقية','أكمل قبل الانتقال'])}
posts=[]
for i,chunk in enumerate((out/'posts.txt').read_text().strip().split('\n---\n'),1):
    main,capsule,story,action=chunk.strip().split('\n|'); title,body=main.split('\n',1); week=min((i-1)//7,4)
    d={'day':i,'date':f'2026-11-{i:02}','weekday':['الاثنين','الثلاثاء','الأربعاء','الخميس','الجمعة','السبت','الأحد'][datetime.date(2026,11,i).weekday()],'week':week+1,'theme':weeks[week],'title':title,'body':body,'capsule':capsule,'story':story,'action':action,'time':'20:00','timezone':'Africa/Cairo','diagram':f'diagram-{i:02}.svg' if i in diagrams else None}
    d['visualPrompt']=f'تصميم تحريري رأسي 1080×1350 لموضوع «{title}». مشهد مكتب طالب مصري واقعي وهادئ، كتاب مفتوح وقلم، بدون درجات أو ساعات أو جداول أو ملامح بائسة. تفصيلة بصرية تعبّر عن: {action} فراغ علوي لوضع العنوان يدويًا بعد التوليد. ألوان كحلي وورقي دافئ ولمسة أخضر. عنصر رئيسي واحد، تباين واضح، دون زخرفة أو نص مولّد داخل الصورة، دون ادعاء نتائج أو مقارنة بين طالب ناجح وفاشل.'
    if i in [1,3,5,8,10,13,15,17,19,22,25,30]:
        paras=body.split('\n\n'); d['carousel']=[title]+paras+[capsule]
    posts.append(d)
assert len(posts)==30
(out/'data.json').write_text(json.dumps(posts,ensure_ascii=False,indent=2))
for day,(title,steps) in diagrams.items():
    def lines(s,n): return textwrap.wrap(s,n,break_long_words=False,break_on_hyphens=False)
    parts=['<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1350" viewBox="0 0 1080 1350" role="img" aria-labelledby="title desc">',f'<title id="title">{html.escape(title)}</title><desc id="desc">'+html.escape('؛ ثم '.join(steps))+'</desc>','<rect width="1080" height="1350" fill="#101f2b"/>','<g font-family="Arial, sans-serif" text-anchor="middle" direction="rtl">','<text x="540" y="94" fill="#7fe1bb" font-size="30">مذاكراوي • نوفمبر ٢٠٢٦</text>']
    for j,line in enumerate(lines(title,27)): parts.append(f'<text x="540" y="{182+j*60}" fill="#fff5e5" font-size="48" font-weight="bold">{html.escape(line)}</text>')
    for j,step in enumerate(steps):
        y=310+j*205
        parts.append(f'<rect x="90" y="{y}" width="900" height="155" rx="24" fill="#f7f2e8"/>')
        for k,line in enumerate(lines(step,29)): parts.append(f'<text x="540" y="{y+65+k*48}" fill="#102c35" font-size="40">{html.escape(line)}</text>')
        if j<3 and day != 19: parts.append(f'<path d="M540 {y+165} v25 m-12 -12 l12 12 12 -12" stroke="#7fe1bb" fill="none" stroke-width="5"/>')
    parts+=['<text x="540" y="1225" fill="#fff5e5" font-size="31">داخل المهمة الموجودة في جدولك</text>','<text x="540" y="1280" fill="#7fe1bb" font-size="28">أفضل أداء متاح • من غير تكليف إضافي</text>','</g></svg>']; (out/f'diagram-{day:02}.svg').write_text('\n'.join(parts))
md=['# نوفمبر ٢٠٢٦ — شغّل اللي في إيدك\n\nخطة تحرير ونشر كاملة لمذاكراوي. ٣٠ بوستًا أصليًا + ٣٠ كبسولة + ٣٠ ستوري + ١٢ كاروسيل + ٨ ديجرامات + ٤ نصوص ريلز/فويس.\n\n## عهد المحتوى\n\nالطالب ينفّذ الموجود في جدوله بأفضل أداء متاح حسب طاقته. لا طلب لعمل جدول أو تعديله، ولا ساعات إضافية، ولا واجبات أو عدد أسئلة جديد، ولا سهر تعويضي. أي اقتراح صغير يحدث أثناء المهمة المقررة. لا ضمان درجات، ولا تشخيص نفسي، ولا تخويف أو إذلال. القصص مشاهد توضيحية متخيلة وليست شهادات طلاب حقيقية.\n\n## طريقة النشر للفريق\n\n- المنطقة الزمنية: Africa/Cairo. الساعة ٨ مساءً اقتراح تحريري، وليست نتيجة تحليل وصول.\n- رسالة رئيسية واحدة يوميًا على فيسبوك. كبسولتها بديل مختصر لتليجرام/واتساب، وليست رسالة إضافية إجبارية لنفس الطالب.\n- ستوري اختياري الساعة ٦ مساءً. عدم الرد طبيعي؛ لا نطلب بيانات شخصية أو درجات.\n- في أيام الكاروسيل يُستخدم بدل المنشور النصي على نفس المنصة، وليس تكرارًا له. الرسالة الكاملة تظل متاحة للكابشن.\n- الريلز بديل لنفس رسالة اليوم. لا نضغط على الفريق أو الجمهور بتوزيع كل الصيغ معًا.\n- لو بدأ النشر بعد أول نوفمبر، ابدأ برسالة تاريخ اليوم، واحتفظ بالأيام السابقة في المكتبة؛ لا تنشر الفائت دفعة واحدة.\n- ملف CSV سجل تحريري عام، لا ندّعي توافقه المباشر مع أدوات الجدولة. النشر الفعلي يدوي أو بعد تحويله لقالب المنصة.\n\n## خريطة الشهر\n\n| الفترة | الهدف |\n|---|---|\n| ١–٧ | تقليل المحاكمة والمقارنة، والعودة للمطلوب |\n| ٨–١٤ | قراءة السؤال، فهم الشرح والتصحيح، ومحاولة أمينة |\n| ١٥–٢١ | التعامل مع منتصف الشهر والفتور والراحة |\n| ٢٢–٢٨ | ضغط البيت، التعطّل، دقة التنفيذ وطلب المساعدة |\n| ٢٩–٣٠ | تقدير الخبرة واستمرار التنفيذ من غير انقلاب على اليوم |\n\n## تقويم الرسائل\n\n| التاريخ | اليوم | الرسالة | الصيغة البصرية المتاحة |\n|---|---|---|']
for p in posts: md.append(f"| {p['date']} | {p['weekday']} | {p['title']} | {'كاروسيل' if 'carousel' in p else 'بوست'}{' + ديجرام جاهز' if p['diagram'] else ''} |")
for p in posts:
    md += [f"\n## {p['day']:02} — {p['title']}\n\n{p['weekday']} {p['date']} · ٢٠:٠٠ بتوقيت القاهرة · {p['theme']}\n\n### نص البوست الجاهز\n\n{p['title']}\n\n{p['body']}\n\n### كبسولة القناة\n\n{p['capsule']}\n\n### ستوري تفاعلي اختياري\n\n{p['story']}\n\n### قصد الرسالة للفريق\n\n{p['action']}\n\n### توجيه الصورة\n\n{p['visualPrompt']}"]
    if 'carousel' in p:
        md += [f"\n[تحميل صور الكاروسيل كاملة — ZIP](november/carousel-{p['day']:02}.zip) · الصور مرقمة بترتيب النشر، مقاس 1080×1350.\n"]
        md += ['\n### الكاروسيل — نص الشرائح الكامل\n']; md += [f"**شريحة {i}:** {s}\n" for i,s in enumerate(p['carousel'],1)]
    if p['diagram']: md += [f"\n**ديجرام جاهز:** [SVG](november/{p['diagram']}) — [PNG](november/{p['diagram'].replace('.svg','.png')}). لا يعرض أرقامًا بحثية؛ هو شرح للممارسة داخل المهمة."]
md += ['''\n## ٤ نصوص ريلز/فويس جاهزة\n\nمدة كل نص نحو ٣٠–٤٥ ثانية بحسب الإلقاء. صوت هادئ، ترجمة عربية واضحة، بدون عدّاد أو مؤثرات تهويل.\n\n### يوم ٤ — الرجوع مش الفشل\n\n**المشهد:** عين على سطر، ثم القلم يرجع لنفس السطر.\n\n**النص:** «سرحت؟ طب ارجع. استنى، قبل ما تبدأ تقول أنا فاشل ومفيش فايدة… هو السرحان محتاج محاكمة؟ اللحظة اللي لاحظت فيها إنك مش مع الصفحة، دي فرصة ترجع. حط عينك على آخر سطر فاهمه، وكمّل نفس المهمة اللي في جدولك. مش محتاج تبدأ يومك من الأول، ولا تستنى مزاج أحسن. التركيز فيه رجوع، مش بس استمرار. وإنت دلوقتي تقدر ترجع.»\n\n**النص على الشاشة:** لاحظت؟ ارجع لآخر سطر فاهمه.\n\n### يوم ١١ — القلم مش ماكينة تصوير\n\n**المشهد:** إجابتان بينهما اختلاف محدد بدائرة، دون درجة.\n\n**النص:** «نقلت الحل كله وبقى كشكولك جميل. بس ليه الحل بدأ من هنا؟ لو السبب مش واضح، يبقى الشكل اتنقل ولسه الفكرة محتاجة تفهمها. وأنت بتصحّح الواجب الموجود عندك، بص لأول اختلاف غيّر النتيجة. قانون؟ معنى كلمة؟ إشارة؟ افهم الفرق وكمّل تصحيحك. مش طالب منك شغل زيادة. طالب إن الشغل اللي بتعمله فعلًا يوصلك لمعناه.»\n\n**النص على الشاشة:** صحّح السبب، مش شكل الإجابة بس.\n\n### يوم ٢٣ — الصبح مش باقي اليوم\n\n**المشهد:** صفحة مفتوحة وإيد تبدأ من موضع التوقف.\n\n**النص:** «الصبح اتعطّل، مفهوم إنك متضايق. بس ليه باقي اليوم لازم يتحاكم معاه؟ الوقت اللي فات مش هيرجع باللوم، والمهمة اللي قدامك لسه ينفع تديها انتباهك. مش مطلوب تعويض ضخم ولا وعد كبير. ارجع للموجود في جدولك واشتغل بأفضل قدرة عندك. اليوم مش ورقة لو اتبقّعت من طرفها نرميها كلها. فيه سطر لسه ينفع يتكتب كويس.»\n\n**النص على الشاشة:** اشتغل في المساحة المتاحة دلوقتي.\n\n### يوم ٣٠ — نهاية صادقة\n\n**المشهد:** كتاب يُغلق بهدوء، بلا مونتاج جوائز.\n\n**النص:** «نوفمبر خلص. مش لازم نقف نتظاهر إننا بقينا مثاليين. يمكن لسه بتقلق، بس بقيت تعرف ترجع للمطلوب. يمكن لسه بتغلط، بس بقيت تسأل عن السبب. دي خبرة تستحق تتشاف. شكرًا لكل مرة ادّيت المهمة اللي في جدولك انتباهك على قد طاقتك. كمّل. مش محتاج تكسب السنة في ليلة، ولا تثبت قيمتك في ورقة. إنت بتتعلم، وده شغل يستحق الاحترام.»\n\n**النص على الشاشة:** خُد خبرتك معاك، وكمّل.\n\n## ردود جاهزة للمشرف\n\n- «أنا متأخر»: فاهم إن الإحساس تقيل. دلوقتي خلّينا مع المهمة الموجودة عندك، من غير حمل السنة كلها فوقها. لو محتاج توضيحًا فيها، قول لنا النقطة اللي وقفت عندها.\n- «أنا غبي»: الغلطة مش تعريفك. نقدر نبص على السؤال نفسه ونفهم هل المشكلة في المطلوب ولا الفكرة ولا التنفيذ.\n- «مش قادر»: مش لازم تثبت جديتك باستنزاف نفسك. لو التعب شديد أو مستمر، كلم شخصًا موثوقًا يساعدك، وخد دعمًا متخصصًا لو محتاجه.\n- «أعمل جدول إزاي؟»: محتوى السلسلة بيركز على جودة تنفيذ جدولك الموجود. لو عندك متابعة تعليمية، ارجع للمسؤول عنها بخصوص ظروفك؛ هنا نقدر نساعدك تفهم نقطة في المهمة الحالية.\n- «أنا خلصت»: برافو على الشغل اللي اتعمل. خُد حقك في الراحة الموجودة عندك، من غير ما نحوّل الإنجاز لتكليف إضافي.\n\n## ضبط الجودة والقياس للفريق\n\nقبل النشر: راجع اتجاه العربية ووضوح الخط على الهاتف؛ تأكد أن الدعوة للفعل داخل المهمة الحالية؛ احذف أي وعد مضمون أو تعميم نفسي أو تكليف إضافي. لا ننسب الصور أو المخططات لأبحاث. لا نستخدم صور درجات أو طلاب حقيقيين دون إذن.\n\nقارن الحفظ والمشاركة والوصول ونسبة إكمال الريلز بين مواد نفس المنصة والصيغة. سجّل أسئلة الفهم المتكررة لتحسين وضوح الرسائل. هذه مؤشرات للمحتوى، وليست دليلًا أن الدرجات الدراسية تحسنت. لا تطلب درجات الطلاب أو تربط التفاعل بالالتزام.\n\n## ملاحظة الإنتاج\n\nالنصوص محررة داخل المشروع. الديجرامات SVG أصلية بنص عربي قابل للتكبير، ولها نسخ PNG للنشر. برومبتات الصور جاهزة لكنها ليست صورًا مولدة. التوليد الخارجي عبر Gemini يحتاج مفتاحًا صالحًا واتصالًا مصرحًا؛ لا نعتبره منفذًا دون استجابة ناجحة.\n''']
(root/'mozakrawi-november-2026-complete.md').write_text('\n'.join(md))
with (out/'schedule.csv').open('w',encoding='utf-8-sig',newline='') as f:
    w=csv.writer(f); w.writerow(['date','weekday','time','timezone','title','post','capsule','story','asset','status'])
    for p in posts: w.writerow([p['date'],p['weekday'],p['time'],p['timezone'],p['title'],p['title']+'\n\n'+p['body'],p['capsule'],p['story'],p['diagram'] or '', 'draft'])
print('Generated',len(posts),'posts,',sum('carousel' in p for p in posts),'carousels,',len(diagrams),'diagrams')
